function arrow(x1,y1,x2,y2,color){
  var dx=x2-x1, dy=y2-y1, len=Math.hypot(dx,dy)||1;
  var ux=dx/len, uy=dy/len;
  var sx=x1+ux*(R+3), sy=y1+uy*(R+3), ex=x2-ux*(R+5), ey=y2-uy*(R+5);
  layer.line(sx,sy,ex,ey).stroke({color:color||'#c0392b',width:2});
  var px=-uy, py=ux, s=6;
  layer.polygon([ex,ey, ex-ux*s+px*s*0.55, ey-uy*s+py*s*0.55, ex-ux*s-px*s*0.55, ey-uy*s-py*s*0.55])
    .fill(color||'#c0392b');
}

function drawFrame(f){
  layer.clear();
  var vals = f.values, marked = f.marked||0, cmp = f.cmp||null, swp = f.swp||null, bad = f.bad||[];
  // array bar
  var cw=40, x0=(VW-cw*10)/2, y0=18;
  layer.text('A').x(x0-20).y(y0+6).font({size:13,'font-style':'italic'});
  for(var k=1;k<=10;k++){
    var hl = (swp && (swp[0]===k||swp[1]===k)) || (cmp && (cmp[0]===k||cmp[1]===k));
    layer.rect(cw,26).move(x0+(k-1)*cw,y0).fill(hl?'#ffd9a0':(bad.indexOf(k)>=0?'#f6c0c0':'#e8e8e8')).stroke({color:'#333',width:1});
    layer.text(String(vals[k])).cx(x0+(k-1)*cw+cw/2).cy(y0+13).font({size:13,'text-anchor':'middle'});
    layer.text(String(k)).cx(x0+(k-1)*cw+cw/2).y(y0-13).font({size:9,'text-anchor':'middle',fill:'#666'});
  }
  // edges
  for(var e=0;e<EDGES.length;e++){
    var a=POS[EDGES[e][0]], b=POS[EDGES[e][1]];
    layer.line(a[0],a[1],b[0],b[1]).stroke({color:'#333',width:1.2});
  }
  // comparison arrows from marked node to compared nodes
  if(cmp && marked){
    for(var c=0;c<cmp.length;c++){
      if(cmp[c]!==marked && POS[cmp[c]]){
        arrow(POS[marked][0],POS[marked][1],POS[cmp[c]][0],POS[cmp[c]][1]);
      }
    }
  }
  // nodes
  for(var i=1;i<=10;i++){
    var p=POS[i], isM=(i===marked), isBad=bad.indexOf(i)>=0, isSw=swp&&(swp[0]===i||swp[1]===i);
    var fill = isM ? '#7a7a7a' : (isBad ? '#e88' : (isSw ? '#ffd9a0' : '#e8e8e8'));
    var g=layer.group().css('cursor','pointer');
    g.circle(R*2).cx(p[0]).cy(p[1]).fill(fill).stroke({color:'#333',width:1.3});
    g.text(String(vals[i])).cx(p[0]).cy(p[1]).font({size:14,'text-anchor':'middle',fill:isM?'#fff':'#000'});
    g.text(String(i)).x(p[0]-R-9).y(p[1]-R-8).font({size:10,fill:'#333'});
    if(isM) g.text('i').x(p[0]-R-16).y(p[1]-4).font({size:12,'font-style':'italic'});
    (function(idx,node){
      node.on('mousemove',function(ev){showTooltip('A['+idx+'] = '+vals[idx],ev);})
          .on('mouseleave',function(){hideTooltip();})
          .on('click',function(){showPopup('Node '+idx,'Key '+vals[idx]+' at index '+idx+'. Left child 2·'+idx+', right child 2·'+idx+'+1 (if ≤ heap size). In a max-heap this key must be ≥ both children.');});
    })(i,g);
  }
}

var initialFrame = {kind:'init', values:initVals.slice(), marked:0, message:'Initial array as a complete binary tree.'};
drawFrame(initialFrame);

