function violations(vals){
  var bad=[];
  for(var i=1;i<=5;i++){
    var l=2*i, r=2*i+1;
    if(l<=10 && vals[i]<vals[l]){ if(bad.indexOf(i)<0)bad.push(i); if(bad.indexOf(l)<0)bad.push(l); }
    if(r<=10 && vals[i]<vals[r]){ if(bad.indexOf(i)<0)bad.push(i); if(bad.indexOf(r)<0)bad.push(r); }
  }
  return bad;
