function goFrame(i){
  if(!frames.length) return;
  cur = Math.max(0, Math.min(frames.length-1, i));
  var f = frames[cur];
  if(cur === frames.length-1 && f.kind!=='error'){
    f.bad = violations(f.values);
  }
  drawFrame(f);
  document.getElementById('frameCounter').textContent = (cur+1)+' of '+frames.length;
  document.getElementById('frameCaption').textContent = f.message||'';
}

function togglePlay(){
  if(playing){ clearInterval(playTimer); playing=false; document.getElementById('playBtn').textContent='▶ Play'; return; }
  if(!frames.length) return;
  if(cur>=frames.length-1) cur=0;
  playing=true; document.getElementById('playBtn').textContent='⏸ Pause';
  playTimer=setInterval(function(){
    if(cur>=frames.length-1){ togglePlay(); return; }
    goFrame(cur+1);
  }, speed);
}

