var initialFrame = {kind:'init', panel:'a', values:initVals.slice(), marked:5,
  message:'Panel (a): MAX-HEAPIFY(A, 5) — node i = 5 (key 16) is shaded.'};
drawFrame(initialFrame);

/* ── code editor workbench ── */
var SAMPLES = {
  sample: "function maxHeapify(i, heapSize) {\n  let largest = i;\n  const l = left(i), r = right(i);\n  if (l <= heapSize && compare(l, largest)) largest = l;\n  if (r <= heapSize && compare(r, largest)) largest = r;\n  if (largest !== i) {\n    swap(i, largest);\n    mark(largest);\n    maxHeapify(largest, heapSize);\n  }\n}",
  buggy: "function maxHeapify(i, heapSize) {\n  let largest = i;\n  const l = left(i), r = right(i);\n  if (l <= heapSize && compare(l, largest)) largest = l;\n  if (r <= heapSize && compare(r, largest)) largest = r;\n  if (largest !== i) {\n    swap(i, largest);\n    // BUG: missing the recursive call — only one level is fixed\n  }\n}",
  bare: "function maxHeapify(i, heapSize) {\n  // API: value(i), left(i), right(i),\n  //      compare(i,j) -> value(i) > value(j),\n  //      swap(i,j), mark(i)\n\n}"
};
var ta = document.getElementById('heapifyEditorCode');
function loadTab(which){
  ta.value = SAMPLES[which];
  ['tabSample','tabBuggy','tabBare'].forEach(function(id){document.getElementById(id).classList.remove('active');});
  document.getElementById(which==='sample'?'tabSample':which==='buggy'?'tabBuggy':'tabBare').classList.add('active');
}
loadTab('sample');

var frames=[], cur=0, playing=false, speed=450, playTimer=null;

function setStatus(txt,color){ var s=document.getElementById('statusOut'); s.textContent='status: '+txt; s.style.color=color||'#333'; }

function violations(vals){
  var bad=[];
  for(var i=1;i<=5;i++){
    var l=2*i, r=2*i+1;
    if(l<=10 && vals[i]<vals[l]){ if(bad.indexOf(i)<0)bad.push(i); if(bad.indexOf(l)<0)bad.push(l); }
    if(r<=10 && vals[i]<vals[r]){ if(bad.indexOf(i)<0)bad.push(i); if(bad.indexOf(r)<0)bad.push(r); }
  }
  return bad;
}

function goFrame(i){
  if(!frames.length) return;
  cur = Math.max(0, Math.min(frames.length-1, i));
  var f = frames[cur];
  if(cur === frames.length-1 && f.kind!=='error'){
    f.bad = violations(f.values);
  }
  drawFrame(f);
  document.getElementById('frameCounter').textContent = (cur+1)+' of '+frames.length;
  var cap = (f.panel ? 'Panel ('+f.panel+') — ' : '') + (f.message||'');
  document.getElementById('frameCaption').textContent = cap;
}

function togglePlay(){
  if(playing){ clearInterval(playTimer); playing=false; document.getElementById('playBtn').textContent='▶ Play'; return; }
  if(!frames.length) return;
  if(cur>=frames.length-1) cur=0;
  playing=true; document.getElementById('playBtn').textContent='⏸ Pause';
  playTimer=setInterval(function(){
    if(cur>=frames.length-1){ togglePlay(); return; }
    goFrame(cur+1);
  }, speed);
}

function trigger_run(){
  if(playing) togglePlay();
  var slot=document.getElementById('eq-err-heapInput');
  var raw=document.getElementById('heapInput').value.split(',').map(function(s){return Number(s.trim());});
  if(raw.length!==10 || raw.some(function(v){return !isFinite(v);})){
    slot.textContent='Need exactly 10 numbers separated by commas.'; slot.style.display=''; return;
  }
  slot.style.display='none';
  var vals=[null].concat(raw);
  initVals=vals.slice();
  setStatus('running…','#a60');
  document.getElementById('runBtn').disabled=true;
  var src = ta.value;
  var workerSrc =
    "onmessage=function(e){\n"+
    " var vals=e.data.values, frames=[], marked=0, cmp=null, swp=null, ops=0, panel=null;\n"+
    " var CALL_PANEL={5:'a',4:'b',3:'c',2:'d',1:'e'};\n"+
    " function snap(kind,indices,msg){ if(frames.length>4000) throw new Error('frame cap hit (4000)'); frames.push({kind:kind,panel:panel,values:vals.slice(),marked:marked,cmp:cmp?cmp.slice():null,swp:swp?swp.slice():null,message:msg}); }\n"+
    " function chk(i){ if(!Number.isInteger(i)||i<1||i>10) throw new Error('index '+i+' out of range 1..10'); }\n"+
    " function tick(){ if(++ops>20000) throw new Error('operation cap hit — possible infinite loop'); }\n"+
    " function value(i){ tick(); chk(i); snap('value',[i],'value('+i+') = '+vals[i]); return vals[i]; }\n"+
    " function left(i){ tick(); chk(i); snap('index',[i],'left('+i+') = '+(2*i)); return 2*i; }\n"+
    " function right(i){ tick(); chk(i); snap('index',[i],'right('+i+') = '+(2*i+1)); return 2*i+1; }\n"+
    " function compare(i,j){ tick(); chk(i); chk(j); cmp=[i,j]; swp=null; var r=vals[i]>vals[j]; snap('compare',[i,j],'compare A['+i+']='+vals[i]+' with A['+j+']='+vals[j]+' → '+r); var out=r; cmp=null; return out; }\n"+
    " function swap(i,j){ tick(); chk(i); chk(j); var t=vals[i]; vals[i]=vals[j]; vals[j]=t; swp=[i,j]; cmp=null; snap('swap',[i,j],'swap A['+i+'] ↔ A['+j+']'); swp=null; }\n"+
    " function mark(i){ tick(); chk(i); marked=i; snap('mark',[i],'sift position moves to index '+i); }\n"+
    " try{\n"+
    "  var f=new Function('value','left','right','compare','swap','mark', e.data.code+'\\n;return (typeof maxHeapify===\"function\")?maxHeapify:null;');\n"+
    "  var mh=f(value,left,right,compare,swap,mark);\n"+
    "  if(!mh) throw new Error('entry point \"maxHeapify(i, heapSize)\" not found — define a function with that exact name');\n"+
    "  var n=10;\n"+
    "  for(var i=Math.floor(n/2);i>=1;i--){ marked=i; panel=CALL_PANEL[i]; frames.push({kind:'call',panel:panel,values:vals.slice(),marked:i,cmp:null,swp:null,message:'BUILD-MAX-HEAP calls MAX-HEAPIFY(A, '+i+') — its subtrees are already heaps'}); mh(i,n); }\n"+
    "  marked=0; panel='f'; frames.push({kind:'done',panel:'f',values:vals.slice(),marked:0,cmp:null,swp:null,message:'BUILD-MAX-HEAP finished — check the max-heap property'});\n"+
    "  postMessage({ok:true,frames:frames});\n"+
    " }catch(err){ frames.push({kind:'error',panel:panel,values:vals.slice(),marked:marked,cmp:cmp,swp:swp,message:'Error: '+(err&&err.message?err.message:err)}); postMessage({ok:false,frames:frames,error:String(err&&err.message?err.message:err)}); }\n"+
    "};";
  var blob=new Blob([workerSrc],{type:'text/javascript'});
  var url=URL.createObjectURL(blob);
  var w=new Worker(url);
  var done=false;
  var to=setTimeout(function(){ if(!done){ done=true; w.terminate(); URL.revokeObjectURL(url);
    frames.push({kind:'error',panel:null,values:vals.slice(),marked:0,message:'Error: timed out (2s) — possible infinite loop'});
    document.getElementById('runBtn').disabled=false; goFrame(frames.length-1); setStatus('error: timeout','#c00'); } },2000);
  w.onmessage=function(ev){
    if(done) return; done=true; clearTimeout(to); w.terminate(); URL.revokeObjectURL(url);
    frames=ev.data.frames; cur=0;
    document.getElementById('runBtn').disabled=false;
    if(!ev.data.ok){ goFrame(frames.length-1); setStatus('error: '+ev.data.error,'#c00'); return; }
    var bad=violations(frames[frames.length-1].values);
    if(bad.length===0){ setStatus('correct — max-heap property holds, root = '+frames[frames.length-1].values[1],'#080'); }
    else{ setStatus('wrong answer — heap property fails at '+bad.length+' node(s), shown in red','#c00'); }
    goFrame(0); togglePlay();
  };
  w.onerror=function(err){
    if(done) return; done=true; clearTimeout(to); w.terminate(); URL.revokeObjectURL(url);
    document.getElementById('runBtn').disabled=false;
    frames=[{kind:'error',panel:null,values:vals.slice(),marked:0,message:'Error: '+(err.message||'script error')}];
    goFrame(0); setStatus('error: '+(err.message||'script error'),'#c00');
  };
  w.postMessage({code:src, values:vals});
}

