var stepIdx=0;
function applyStep(k){
  stepIdx=Math.max(0,Math.min(STEPS.length-1,k));
  document.getElementById('demoNarration').textContent=STEPS[stepIdx].n;
  document.getElementById('stepLabel').textContent=(stepIdx+1)+' / '+STEPS.length;
  if(playing) togglePlay();
  STEPS[stepIdx].run();
}
function prevStep(){ applyStep(stepIdx-1); }
function nextStep(){ applyStep(stepIdx+1); }

